-- 조건이 여러 개인 리눅스 문제를 조건별 채점으로 승격 (세트 15 #7·#12, 16 #3·#9, 21 #14, 27 #13, 35 #3). grade_cmd 는 그대로, 같은 조건을 && 로 이은 것과 같다.
UPDATE quest SET checks = '[{"label": "포트가 port=9090 으로 바뀌었다", "cmd": ["sh", "-c", "grep -qx ''port=9090'' /etc/app/app.conf"]}, {"label": "host=0.0.0.0 줄이 그대로 있다", "cmd": ["sh", "-c", "grep -qx ''host=0.0.0.0'' /etc/app/app.conf"]}, {"label": "timeout=30 줄이 그대로 있다", "cmd": ["sh", "-c", "grep -qx ''timeout=30'' /etc/app/app.conf"]}, {"label": "옛 포트 8080 이 어디에도 남아 있지 않다", "cmd": ["sh", "-c", "! grep -q 8080 /etc/app/app.conf"]}, {"label": "파일이 여전히 6줄이다 (다른 줄이 지워지지 않았다)", "cmd": ["sh", "-c", "[ \\"$(wc -l < /etc/app/app.conf)\\" -eq 6 ]"]}]' WHERE quest_set_id = 15 AND order_index = 12;
UPDATE quest SET checks = '[{"label": "최근 로그 recent.log 는 남아 있다", "cmd": ["sh", "-c", "[ -f /var/log/old-app/recent.log ]"]}, {"label": "30일 된 old1.log, old2.log 가 삭제됐다", "cmd": ["sh", "-c", "[ ! -e /var/log/old-app/old1.log ] && [ ! -e /var/log/old-app/old2.log ]"]}, {"label": "10일 된 old3.log 도 삭제됐다 (7일보다 오래된 파일)", "cmd": ["sh", "-c", "[ ! -e /var/log/old-app/old3.log ]"]}]' WHERE quest_set_id = 16 AND order_index = 3;
UPDATE quest SET checks = '[{"label": "deploy 사용자가 로그 폴더에 파일을 만들 수 있다", "cmd": ["sh", "-c", "su deploy -s /bin/sh -c ''touch /srv/app/logs/t.log''"]}, {"label": "아무나 쓸 수 있게(o+w) 열어 두지 않았다", "cmd": ["sh", "-c", "! find /srv/app/logs -maxdepth 0 -perm -o+w | grep -q ."]}]' WHERE quest_set_id = 16 AND order_index = 9;
UPDATE quest SET checks = '[{"label": "/etc/exports 에 /export/data 공유 줄이 있다", "cmd": ["sh", "-c", "grep -q ''^/export/data[[:space:]]'' /etc/exports"]}, {"label": "접속 허용 대역이 10.0.0.0/24 이다", "cmd": ["sh", "-c", "grep ''^/export/data[[:space:]]'' /etc/exports | grep -q ''10[.]0[.]0[.]0/24''"]}, {"label": "읽기·쓰기(rw) 옵션이 있다", "cmd": ["sh", "-c", "grep ''^/export/data[[:space:]]'' /etc/exports | grep -q ''rw''"]}, {"label": "sync 옵션이 있다", "cmd": ["sh", "-c", "grep ''^/export/data[[:space:]]'' /etc/exports | grep -q ''sync''"]}, {"label": "no_root_squash 옵션이 있다", "cmd": ["sh", "-c", "grep ''^/export/data[[:space:]]'' /etc/exports | grep -q ''no_root_squash''"]}]' WHERE quest_set_id = 27 AND order_index = 13;
UPDATE quest SET checks = '[{"label": "첫 줄이 기존 내용(first line) 그대로다", "cmd": ["sh", "-c", "[ \\"$(head -n 1 /tmp/notes.txt)\\" = ''first line'' ]"]}, {"label": "둘째 줄에 second line 이 추가됐다", "cmd": ["sh", "-c", "[ \\"$(sed -n 2p /tmp/notes.txt)\\" = ''second line'' ]"]}, {"label": "파일이 정확히 2줄이다 (덮어쓰거나 중복되지 않았다)", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/notes.txt)\\" -eq 2 ]"]}]' WHERE quest_set_id = 15 AND order_index = 7;
UPDATE quest SET checks = '[{"label": "두 파일이 같은 inode 를 가리킨다 (하드링크)", "cmd": ["sh", "-c", "[ \\"$(stat -c %i /tmp/orig.txt)\\" = \\"$(stat -c %i /tmp/hard.txt)\\" ]"]}, {"label": "링크 수가 2 이다", "cmd": ["sh", "-c", "[ \\"$(stat -c %h /tmp/orig.txt)\\" = 2 ]"]}, {"label": "심볼릭 링크가 아니라 하드링크다", "cmd": ["sh", "-c", "[ ! -L /tmp/hard.txt ]"]}]' WHERE quest_set_id = 21 AND order_index = 14;
UPDATE quest SET checks = '[{"label": "/tmp/seq 에 파일이 5개 만들어졌다", "cmd": ["sh", "-c", "[ \\"$(ls /tmp/seq | wc -l)\\" -eq 5 ]"]}, {"label": "file1.txt 가 있다", "cmd": ["sh", "-c", "[ -f /tmp/seq/file1.txt ]"]}, {"label": "file5.txt 가 있다", "cmd": ["sh", "-c", "[ -f /tmp/seq/file5.txt ]"]}]' WHERE quest_set_id = 35 AND order_index = 3;
